94	    void CaresPTRResolver::wait()
95	    {
96	        timeval * tvp, tv;
97	        fd_set read_fds;
98	        fd_set write_fds;
99	        int nfds;
100	
101	        for (;;)
102	        {
103	            FD_ZERO(&read_fds);
104	            FD_ZERO(&write_fds);
105	            nfds = ares_fds(channel, &read_fds,&write_fds);
106	            if (nfds == 0)
107	            {
108	                break;
109	            }
110	            tvp = ares_timeout(channel, nullptr, &tv);
111	            select(nfds, &read_fds, &write_fds, nullptr, tvp);
112	            ares_process(channel, &read_fds, &write_fds);
113	        }
114	    }
